parameters.list:
={{
(raw => {
  let t = (raw || "").toString().replace(/\s+/g, "").replace(/\D/g, "");
  t = t.replace(/^0+/, "");

  if (t.length === 8) {
    // número sem DDD
    t = "11" + "9" + t;
  } else if (t.length === 9) {
    // celular sem DDD
    t = "11" + t;
  } else if (t.length === 10) {
    // DDD + telefone sem 9
    t = t.replace(/^(\d{2})(\d{8})$/, "$19$2");
  } else if (t.length === 11) {
    // DDD + celular
    t = "55" + t;
  } else if (t.length === 12) {
    // 55 + DDD + telefone sem 9
    t = t.slice(0, 4) + "9" + t.slice(4);
  } else if (t.length > 13) {
    // mantém apenas os últimos 13 dígitos
    t = t.slice(-13);
  }

  return t;
})($('Intervalo entre mensagens1').first().json.whatsapp)
}}_mem_agent_FINAMOB_SDR

